-- AI/ML pathway ("Cipher Division") Act 18 -- "Experimentation" content.
-- Closes Arc III ("Neural Systems", Acts 13-18). Elena Rook leads: a real
-- experimentation discipline (hypotheses, baselines, controlled experiments,
-- tuning, learning curves, bias/variance, ablations, error analysis,
-- reproducibility, experiment tracking, model selection) applied to a
-- suspiciously perfect new model variant, before the pathway pivots into
-- computer vision next Act.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. World/act/pathway
-- rows already exist (world-ai-experimentation, act-ai-3) and are not
-- touched, nor is dialogue_lines_character_id_check.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-experimentation', 'world-ai-experimentation', 'experimentation', '18A - Experimentation', 'Turn ad hoc modeling into a real discipline -- hypotheses, baselines, controlled experiments, tuning, learning curves, bias/variance, ablations, error analysis, reproducibility, tracking and model selection -- before this Arc closes.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-experimentation-1', 'campaign-ai-experimentation', 'ask-before-you-tune', 'Ask Before You Tune', 'Hypotheses, baselines, controlled experiments, hyperparameter tuning, learning curves and bias vs variance -- the discipline that has to exist before a single knob gets turned.', 1),
  ('operation-ai-experimentation-2', 'campaign-ai-experimentation', 'prove-it-or-drop-it', 'Prove It or Drop It', 'Ablations, error analysis, reproducibility, experiment tracking and model selection, aimed straight at a result that looks too good to be true.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-experimentation-01', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'hypotheses', 'Hypotheses', 'A new model variant just beat every baseline this Arc has built, by a wide margin, on the first try. Maya wants to know why before anyone updates a single production system.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"hypotheses-intro-sim"}'::jsonb, '{"xp":340,"credits":80}'::jsonb, false, 1),
  ('mission-ai-experimentation-02', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'baselines', 'Baselines', 'A number means nothing alone. Without a baseline to beat, "94% accuracy" could be a triumph or an embarrassment, and there is no way to tell which.', 'beginner', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"baselines-sim"}'::jsonb, '{"xp":350,"credits":85}'::jsonb, false, 2),
  ('mission-ai-experimentation-03', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'controlled-experiments', 'Controlled Experiments', 'Change one thing at a time, or lose the right to say what caused the improvement. Change five things at once and the credit assignment is a guess.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-experimentation-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"controlled-experiments-sim"}'::jsonb, '{"xp":350,"credits":85}'::jsonb, false, 3),
  ('mission-ai-experimentation-04', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'hyperparameter-tuning', 'Hyperparameter Tuning', 'Learning rate, batch size, layer count -- none of them get learned from data. Somebody, or some search process, has to choose them on purpose.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"hyperparameter-tuning-sim"}'::jsonb, '{"xp":360,"credits":85}'::jsonb, false, 4),
  ('mission-ai-experimentation-05', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'learning-curves', 'Learning Curves', 'Plot training and validation error against how much data or how many epochs a model has seen, and the shape of the two lines tells its own story.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-experimentation-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"learning-curves-sim"}'::jsonb, '{"xp":360,"credits":90}'::jsonb, false, 5),
  ('mission-ai-experimentation-06', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-1', 'bias-vs-variance', 'Bias vs Variance', 'Too simple and a model cannot even fit the data it was trained on. Too flexible and it fits that data perfectly, then falls apart on anything new.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"bias-variance-sim"}'::jsonb, '{"xp":370,"credits":90}'::jsonb, false, 6),
  ('mission-ai-experimentation-07', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'ablations', 'Ablations', 'Remove one piece of the new variant at a time and watch what actually breaks. Whatever still works fine without it was never the reason for the improvement.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"ablations-sim"}'::jsonb, '{"xp":370,"credits":90}'::jsonb, false, 7),
  ('mission-ai-experimentation-08', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'error-analysis', 'Error Analysis', 'An aggregate score hides where a model actually fails. Reading the individual mistakes finds the pattern the score never could.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"error-analysis-sim"}'::jsonb, '{"xp":380,"credits":95}'::jsonb, false, 8),
  ('mission-ai-experimentation-09', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'reproducibility', 'Reproducibility', 'A result that only happens once is not a result, it is an anecdote. Noah has watched too many "breakthroughs" die the second someone reran the code.', 'intermediate', ARRAY['elena','noah'], '{"requiredMissionIds":["mission-ai-experimentation-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"reproducibility-sim"}'::jsonb, '{"xp":380,"credits":95}'::jsonb, false, 9),
  ('mission-ai-experimentation-10', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'experiment-tracking', 'Experiment Tracking', 'A notebook is not a product, and neither is a folder of scripts named final_v2_REAL. Noah wants every run logged: config, data version, seed, metrics, all of it.', 'intermediate', ARRAY['noah'], '{"requiredMissionIds":["mission-ai-experimentation-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"experiment-tracking-sim"}'::jsonb, '{"xp":390,"credits":95}'::jsonb, false, 10),
  ('mission-ai-experimentation-11', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'model-selection', 'Model Selection', 'The best model is not the one with the highest single number. It is the one that wins for the right reasons, under the constraints that actually matter.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-experimentation-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"model-selection-sim"}'::jsonb, '{"xp":390,"credits":100}'::jsonb, false, 11),
  ('mission-ai-experimentation-12', 'world-ai-experimentation', 'campaign-ai-experimentation', 'operation-ai-experimentation-2', 'the-false-improvement', 'The False Improvement', 'The variant that beat every baseline on the first try, put through a real ablation, a seed-sensitivity check, and an honest comparison -- to find out if it earned that win.', 'boss', ARRAY['maya','elena','noah'], '{"requiredMissionIds":["mission-ai-experimentation-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"false-improvement-boss-sim"}'::jsonb, '{"xp":920,"credits":205,"badgeIds":["the-false-improvement"],"skillXp":{"ml_experimentation":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-experimentation-01', 1, 'elena', 'Elena Rook. A new model variant just landed on my desk -- it beat every baseline this Arc has built, by a wide margin, on the very first training run.'),
  ('mission-ai-experimentation-01', 2, 'maya', 'Which is exactly why nobody is touching production with it yet. In my experience, a result that good on the first try is either a genuine breakthrough or a mistake that has not been found. Those look identical from the outside.'),
  ('mission-ai-experimentation-01', 3, 'maya', 'Before this Arc closes, Cipher Division is going to run a real experimentation discipline on it -- hypotheses, baselines, controlled tests, all of it. Not because I doubt the number. Because I have not yet earned the right to trust it.'),
  ('mission-ai-experimentation-01', 4, 'elena', 'Step one, before any of that: a hypothesis. A specific, falsifiable claim about why this variant should do better -- not just excitement that it did.'),

  ('mission-ai-experimentation-02', 1, 'elena', 'Ninety-four percent accuracy. Said on its own, that number is meaningless. Ninety-four percent compared to what?'),
  ('mission-ai-experimentation-02', 2, 'elena', 'A baseline is the simplest reasonable comparison point -- a majority-class guess, a basic linear model, the previous Act''s model. Beat the baseline by a wide margin and a result means something. Beat it by nothing and the fancy new variant just added complexity for free.'),
  ('mission-ai-experimentation-02', 3, 'elena', 'Nobody set a baseline before running this variant. That gap gets fixed today, before we go any further.'),

  ('mission-ai-experimentation-03', 1, 'elena', 'A controlled experiment changes exactly one thing between two runs, and holds everything else fixed -- same data split, same preprocessing, same seed, same hardware. Whatever changes in the result can then be attributed to that one thing.'),
  ('mission-ai-experimentation-03', 2, 'byte', 'Change the architecture and the learning rate and the data split all at once, and a better score tells you almost nothing. It could be any of the three, or some combination fighting each other.'),
  ('mission-ai-experimentation-03', 3, 'elena', 'The variant that landed on my desk changed at least three things at once compared to the old model. That alone should have been a warning sign before anyone got excited about the number.'),

  ('mission-ai-experimentation-04', 1, 'elena', 'Hyperparameters are the settings training does not learn on its own -- learning rate, batch size, number of layers, regularization strength. Someone, or some search process, has to choose them.'),
  ('mission-ai-experimentation-04', 2, 'elena', 'Grid search tries every combination in a fixed set, exhaustively but expensively. Random search samples combinations at random, which often finds a good setting faster because it does not waste effort on unimportant parameters.'),
  ('mission-ai-experimentation-04', 3, 'elena', 'Either way, tuning happens against a validation set, never the test set. Tune against the test set and you have not tuned the model -- you have leaked the test set into training by another name.'),

  ('mission-ai-experimentation-05', 1, 'elena', 'A learning curve plots error against how much training data, or how many epochs, a model has seen -- one line for training error, one for validation error.'),
  ('mission-ai-experimentation-05', 2, 'byte', 'The shape says more than either number alone. Both curves flattening high and close together means the model is too simple. A big, persistent gap between them means it is memorizing instead of generalizing.'),
  ('mission-ai-experimentation-05', 3, 'elena', 'Read correctly, a learning curve tells you what to fix before you waste a single hour tuning the wrong knob.'),

  ('mission-ai-experimentation-06', 1, 'elena', 'Bias is error from a model too simple to capture the real pattern -- it underfits, and training error stays high. Variance is error from a model so flexible it fits noise along with signal -- it overfits, and the gap between training and validation error stays wide.'),
  ('mission-ai-experimentation-06', 2, 'elena', 'Every model sits somewhere on that tradeoff. Fixing bias usually means more capacity or better features. Fixing variance usually means more data, regularization, or a simpler model.'),
  ('mission-ai-experimentation-06', 3, 'elena', 'Diagnose which one you actually have before reaching for a fix -- the two problems have opposite cures, and applying the wrong one makes things worse.'),

  ('mission-ai-experimentation-07', 1, 'elena', 'An ablation removes or disables one component of a model at a time and measures what actually happens to performance. Whatever the score does not care about was never the reason for the win.'),
  ('mission-ai-experimentation-07', 2, 'elena', 'The variant that started this Arc has four things different from the old model. Time to strip them out one at a time and see which one the score actually depends on.'),

  ('mission-ai-experimentation-08', 1, 'elena', 'A single accuracy number hides every individual mistake behind it. Error analysis means actually reading a sample of what the model got wrong, not just the aggregate score.'),
  ('mission-ai-experimentation-08', 2, 'elena', 'Patterns hide in the mistakes that never show up in the summary -- a model that is fine on average but consistently wrong on one specific slice of the data.'),

  ('mission-ai-experimentation-09', 1, 'elena', 'Reproducibility is the requirement that the same code, on the same data, with the same seed, produces the same result -- every time, not just the one time someone happened to get lucky.'),
  ('mission-ai-experimentation-09', 2, 'noah', 'Noah Kim. I have watched more "breakthroughs" die on a second run than I can count. Different seed, slightly different data shuffle, and the number that impressed everyone quietly disappears.'),
  ('mission-ai-experimentation-09', 3, 'noah', 'If a result cannot survive being run twice, it is not a result. It is a coin flip that landed well once.'),

  ('mission-ai-experimentation-10', 1, 'noah', 'A notebook is not a product, and neither is a folder full of scripts named final_v2_REAL and final_v2_REAL_ACTUAL. Nobody can tell which run produced which number six months from now.'),
  ('mission-ai-experimentation-10', 2, 'noah', 'Experiment tracking means every run gets logged automatically -- the exact code version, the data version, the hyperparameters, the random seed, and every metric. If it is not logged, it did not happen as far as this team is concerned.'),

  ('mission-ai-experimentation-11', 1, 'elena', 'Model selection is not "pick whichever number is highest." It is picking the model that wins for defensible reasons, under the constraints that actually apply -- latency, memory, fairness across groups, cost to retrain.'),
  ('mission-ai-experimentation-11', 2, 'elena', 'A model that is 0.3% more accurate but three times slower and far more expensive to retrain is not automatically the better choice. That decision depends on what the system actually needs, not on a single leaderboard number.'),

  ('mission-ai-experimentation-12', 1, 'maya', 'Everything this Arc built comes down to one question: does the variant that started this Act actually deserve the win it claimed, or not.'),
  ('mission-ai-experimentation-12', 2, 'elena', 'Three checks, run properly this time. Was the comparison against the old model actually controlled. Does the result survive a change of random seed. And what does a real ablation say actually caused the difference.'),
  ('mission-ai-experimentation-12', 3, 'noah', 'I pulled the run logs myself. Every number is right there, timestamped, with every setting that produced it. No guessing this time.'),
  ('mission-ai-experimentation-12', 4, 'elena', 'And the answer is no. The improvement does not survive a controlled ablation. It came from an easier evaluation set and a lucky random seed, not from anything the new variant actually does better.'),
  ('mission-ai-experimentation-12', 5, 'maya', 'Which is exactly why this discipline exists. Not to kill good results -- to stop bad ones from reaching production wearing a good result''s numbers.'),
  ('mission-ai-experimentation-12', 6, 'maya', 'A real experimentation discipline is finally in place. Everything built through this Arc has been numbers and structured data -- tables, features, sequences, all of it. Cipher Labs runs on cameras too, and nobody has taught a model to read one yet.'),
  ('mission-ai-experimentation-12', 7, 'elena', 'That is the next Arc. Not one more number to distrust -- an entirely new kind of input. Time to teach a model to see.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-experimentation-01-o1', 'mission-ai-experimentation-01', 1, 'Recognize the trap', 'State why an unusually strong first-try result deserves suspicion, not immediate trust.'),
  ('mission-ai-experimentation-01-o2', 'mission-ai-experimentation-01', 2, 'Write a real hypothesis', 'Choose the statement that qualifies as a genuine, falsifiable hypothesis.'),

  ('mission-ai-experimentation-02-o1', 'mission-ai-experimentation-02', 1, 'Judge the number', 'Determine what a reported accuracy actually needs before it means anything.'),
  ('mission-ai-experimentation-02-o2', 'mission-ai-experimentation-02', 2, 'Pick the right baseline', 'Choose the strongest reasonable baseline for a given prediction task.'),

  ('mission-ai-experimentation-03-o1', 'mission-ai-experimentation-03', 1, 'Define control', 'State what a controlled experiment actually isolates.'),
  ('mission-ai-experimentation-03-o2', 'mission-ai-experimentation-03', 2, 'Spot the confound', 'Find the evidence showing a comparison was not actually controlled.'),

  ('mission-ai-experimentation-04-o1', 'mission-ai-experimentation-04', 1, 'Know the boundary', 'Identify what makes a setting a hyperparameter rather than a learned parameter.'),
  ('mission-ai-experimentation-04-o2', 'mission-ai-experimentation-04', 2, 'Protect the test set', 'Judge whether a tuning setup keeps the test set honest.'),

  ('mission-ai-experimentation-05-o1', 'mission-ai-experimentation-05', 1, 'Read the shape', 'Diagnose what a described learning curve shape actually indicates.'),
  ('mission-ai-experimentation-05-o2', 'mission-ai-experimentation-05', 2, 'Match curve to fix', 'Match each learning curve pattern to the problem it signals.'),

  ('mission-ai-experimentation-06-o1', 'mission-ai-experimentation-06', 1, 'Diagnose the tradeoff', 'Determine whether a described model is suffering from high bias or high variance.'),
  ('mission-ai-experimentation-06-o2', 'mission-ai-experimentation-06', 2, 'Match symptom to cause', 'Match each symptom to bias, variance, or a good fit.'),

  ('mission-ai-experimentation-07-o1', 'mission-ai-experimentation-07', 1, 'Define the method', 'State what an ablation study is actually designed to test.'),
  ('mission-ai-experimentation-07-o2', 'mission-ai-experimentation-07', 2, 'Read the ablation', 'Find the evidence showing which component the score actually depends on.'),

  ('mission-ai-experimentation-08-o1', 'mission-ai-experimentation-08', 1, 'Know the limit of a score', 'State what an aggregate accuracy score cannot tell you on its own.'),
  ('mission-ai-experimentation-08-o2', 'mission-ai-experimentation-08', 2, 'Find the pattern', 'Find the evidence revealing a consistent pattern hidden inside the model''s errors.'),

  ('mission-ai-experimentation-09-o1', 'mission-ai-experimentation-09', 1, 'Define reproducibility', 'State what it actually means for a result to be reproducible.'),
  ('mission-ai-experimentation-09-o2', 'mission-ai-experimentation-09', 2, 'Judge the retest', 'Find the evidence showing a result failed to reproduce.'),

  ('mission-ai-experimentation-10-o1', 'mission-ai-experimentation-10', 1, 'Know what tracking buys you', 'State the actual purpose of logging every experiment run.'),
  ('mission-ai-experimentation-10-o2', 'mission-ai-experimentation-10', 2, 'Spot the untracked run', 'Find the evidence showing a run that cannot be trusted because it was never properly logged.'),

  ('mission-ai-experimentation-11-o1', 'mission-ai-experimentation-11', 1, 'Reject the wrong criterion', 'State why picking a model on raw accuracy alone can be the wrong call.'),
  ('mission-ai-experimentation-11-o2', 'mission-ai-experimentation-11', 2, 'Select under constraints', 'Choose the model that is actually the better production choice given real constraints.'),

  ('mission-ai-experimentation-12-o1', 'mission-ai-experimentation-12', 1, 'Audit the comparison', 'Judge whether the original comparison between the old model and the new variant was actually controlled.'),
  ('mission-ai-experimentation-12-o2', 'mission-ai-experimentation-12', 2, 'Test seed sensitivity', 'Judge whether the variant''s improvement survives a change of random seed.'),
  ('mission-ai-experimentation-12-o3', 'mission-ai-experimentation-12', 3, 'Run the real ablation', 'Find what the ablation shows actually explains the score difference.'),
  ('mission-ai-experimentation-12-o4', 'mission-ai-experimentation-12', 4, 'Deliver the verdict', 'Having audited the comparison, the seed sensitivity and the ablation, state whether the improvement is real.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-experimentation-01-o1-c1', 'mission-ai-experimentation-01-o1', 1, 'multiple_choice', 'A brand-new model variant beats every baseline by a wide margin on its very first run. What is the right first reaction?', '{"question":"A brand-new model variant beats every baseline by a wide margin on its very first run. What is the right first reaction?","options":[{"id":"a","text":"Ship it immediately, a strong number speaks for itself"},{"id":"b","text":"Treat it as suspicious until the experiment that produced it can be checked, since a mistake and a breakthrough can look identical"},{"id":"c","text":"Ignore it, first runs never matter"},{"id":"d","text":"Assume it is fraud and discard it without checking"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-01-o2-c1', 'mission-ai-experimentation-01-o2', 1, 'multiple_choice', 'Which of these actually qualifies as a testable hypothesis for why the new variant might do better?', '{"question":"Which of these actually qualifies as a testable hypothesis for why the new variant might do better?","options":[{"id":"a","text":"This model feels more advanced"},{"id":"b","text":"Adding the extra normalization layer will reduce validation error compared to the old architecture, holding data and training setup fixed"},{"id":"c","text":"The new model is simply better"},{"id":"d","text":"Something in the new version probably helped"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-experimentation-02-o1-c1', 'mission-ai-experimentation-02-o1', 1, 'multiple_choice', 'A model reports 94% accuracy on a task. What does that number actually require before it means anything?', '{"question":"A model reports 94% accuracy on a task. What does that number actually require before it means anything?","options":[{"id":"a","text":"Nothing, a high percentage is always good news"},{"id":"b","text":"A baseline to compare it against, such as a simple majority-class guess or a basic model"},{"id":"c","text":"A bigger dataset, regardless of the comparison"},{"id":"d","text":"More decimal places"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-02-o2-c1', 'mission-ai-experimentation-02-o2', 1, 'investigation', 'A dataset for detecting a rare event is 98% "normal" and 2% "event." Which baseline is actually the strongest reasonable comparison point?', '{"evidence":[{"id":"e1","label":"Always predict normal","detail":"A majority-class baseline that would already score 98% accuracy on this data by never once predicting the rare event"},{"id":"e2","label":"Random guess baseline","detail":"Predicts normal or event with equal 50/50 probability, scoring far below 98% accuracy"},{"id":"e3","label":"Previous Act''s simple model","detail":"A basic linear model already deployed, scoring 91% accuracy with meaningful detections of the rare event"}],"question":"Which baseline is actually the strongest, most informative comparison point here?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-experimentation-03-o1-c1', 'mission-ai-experimentation-03-o1', 1, 'multiple_choice', 'A controlled experiment is best described as one that...', '{"question":"A controlled experiment is best described as one that...","options":[{"id":"a","text":"Changes as many things as possible at once to maximize the chance of improvement"},{"id":"b","text":"Changes exactly one variable between runs while holding everything else fixed, so any difference in result can be attributed to that one change"},{"id":"c","text":"Only ever uses the largest available dataset"},{"id":"d","text":"Requires no baseline at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-03-o2-c1', 'mission-ai-experimentation-03-o2', 1, 'investigation', 'Which evidence shows the comparison between the old model and the new variant was not actually controlled?', '{"evidence":[{"id":"e1","label":"Run config diff","detail":"The new variant changed the architecture, the learning rate, and the train/validation split all in the same run compared to the old model"},{"id":"e2","label":"Hardware log","detail":"Both runs used the same GPU type"},{"id":"e3","label":"Code repository","detail":"Both runs used version-controlled code with a recorded commit hash"}],"question":"Which evidence shows the comparison was not actually controlled?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-experimentation-04-o1-c1', 'mission-ai-experimentation-04-o1', 1, 'multiple_choice', 'What makes a setting a hyperparameter rather than a learned parameter?', '{"question":"What makes a setting a hyperparameter rather than a learned parameter?","options":[{"id":"a","text":"It is set before training and is not adjusted by the training process itself, such as learning rate or batch size"},{"id":"b","text":"It changes automatically every epoch through backpropagation"},{"id":"c","text":"It only exists in classical machine learning, never in deep learning"},{"id":"d","text":"It is always a single fixed number that never varies across models"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-ai-experimentation-04-o2-c1', 'mission-ai-experimentation-04-o2', 1, 'multiple_choice', 'A team tunes hyperparameters by repeatedly checking performance directly on the test set until it looks best. What is wrong with this setup?', '{"question":"A team tunes hyperparameters by repeatedly checking performance directly on the test set until it looks best. What is wrong with this setup?","options":[{"id":"a","text":"Nothing, the test set exists to be used for tuning"},{"id":"b","text":"It leaks the test set into the tuning process, so the final test score no longer reflects genuinely unseen performance"},{"id":"c","text":"It is wrong only if the model is a neural network"},{"id":"d","text":"It is fine as long as accuracy improves"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-experimentation-05-o1-c1', 'mission-ai-experimentation-05-o1', 1, 'multiple_choice', 'Both training and validation error start high, drop for a while, then flatten out at a similarly high value, close together. What does that shape indicate?', '{"question":"Both training and validation error start high, drop for a while, then flatten out at a similarly high value, close together. What does that shape indicate?","options":[{"id":"a","text":"The model is overfitting badly"},{"id":"b","text":"The model is underfitting -- it lacks the capacity to fit even the training data well"},{"id":"c","text":"The model has already achieved the best possible performance"},{"id":"d","text":"The data must be corrupted"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-05-o2-c1', 'mission-ai-experimentation-05-o2', 1, 'drag_and_drop', 'Match each learning curve pattern to the problem it signals.', '{"items":[{"id":"i1","text":"Training error very low, validation error stays high, with a wide persistent gap"},{"id":"i2","text":"Both training and validation error flatten out high, close together"},{"id":"i3","text":"Both curves converge to a low error and stay close together"}],"targets":[{"id":"t1","label":"High variance (overfitting)"},{"id":"t2","label":"High bias (underfitting)"},{"id":"t3","label":"Good fit"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3"}}'::jsonb),

  ('mission-ai-experimentation-06-o1-c1', 'mission-ai-experimentation-06-o1', 1, 'investigation', 'A model scores poorly on training data and about equally poorly on validation data. What does this describe?', '{"evidence":[{"id":"e1","label":"Metric report","detail":"Training accuracy 61%, validation accuracy 59% -- both low, close together"},{"id":"e2","label":"Metric report B","detail":"Training accuracy 99%, validation accuracy 64% -- large gap"},{"id":"e3","label":"Metric report C","detail":"Training accuracy 92%, validation accuracy 90% -- both high, close together"}],"question":"Which report describes high bias -- a model too simple to fit the data well?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-experimentation-06-o2-c1', 'mission-ai-experimentation-06-o2', 1, 'drag_and_drop', 'Match each symptom to bias, variance, or a good fit.', '{"items":[{"id":"i1","text":"Both training and validation error are high and close together"},{"id":"i2","text":"Training error near zero, validation error much higher"},{"id":"i3","text":"Both training and validation error are low and close together"},{"id":"i4","text":"Adding more training data barely helps"}],"targets":[{"id":"t1","label":"High bias"},{"id":"t2","label":"High variance"},{"id":"t3","label":"Good fit"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t1"}}'::jsonb),

  ('mission-ai-experimentation-07-o1-c1', 'mission-ai-experimentation-07-o1', 1, 'multiple_choice', 'An ablation study is best described as...', '{"question":"An ablation study is best described as...","options":[{"id":"a","text":"Adding as many new components as possible to see if any of them help"},{"id":"b","text":"Removing or disabling one component at a time and measuring what happens to performance, to isolate which part actually matters"},{"id":"c","text":"Retraining the exact same model twice for luck"},{"id":"d","text":"A way to increase a model''s reported accuracy artificially"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-07-o2-c1', 'mission-ai-experimentation-07-o2', 1, 'investigation', 'The new variant changed four things versus the old model. An ablation removes each one individually. Which result shows what the score actually depends on?', '{"evidence":[{"id":"e1","label":"Remove new normalization layer","detail":"Score drops by 0.4%, within normal run-to-run noise"},{"id":"e2","label":"Remove extra training epochs","detail":"Score drops by 0.2%, within normal run-to-run noise"},{"id":"e3","label":"Revert the evaluation set to the same one the old model was scored on","detail":"Score drops by 11%, collapsing almost the entire claimed improvement"}],"question":"Which ablation result shows what the score improvement actually depended on?"}'::jsonb, '{"requiredEvidenceIds":["e3"]}'::jsonb),

  ('mission-ai-experimentation-08-o1-c1', 'mission-ai-experimentation-08-o1', 1, 'multiple_choice', 'What can an aggregate accuracy score never tell you on its own?', '{"question":"What can an aggregate accuracy score never tell you on its own?","options":[{"id":"a","text":"Whether the model was trained at all"},{"id":"b","text":"Where and how the model is actually failing -- which specific cases or slices of data it gets wrong"},{"id":"c","text":"The total number of training examples used"},{"id":"d","text":"What programming language was used to build it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-08-o2-c1', 'mission-ai-experimentation-08-o2', 1, 'investigation', 'Overall accuracy is a solid 89%. Which evidence reveals a pattern the aggregate score hides?', '{"evidence":[{"id":"e1","label":"Error sample review","detail":"Of the 11% of cases the model gets wrong, over 80% belong to a single specific category that makes up only 6% of the overall dataset"},{"id":"e2","label":"Training log","detail":"Training ran for 40 epochs before stopping"},{"id":"e3","label":"Model size","detail":"The model has 12 million parameters"}],"question":"Which evidence reveals a pattern the aggregate accuracy score hides?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-experimentation-09-o1-c1', 'mission-ai-experimentation-09-o1', 1, 'multiple_choice', 'A reproducible result is best described as one where...', '{"question":"A reproducible result is best described as one where...","options":[{"id":"a","text":"It only needs to happen once to be trusted"},{"id":"b","text":"The same code, on the same data, with the same seed, produces the same result consistently, not just on a single lucky run"},{"id":"c","text":"It looks impressive in a demo"},{"id":"d","text":"Nobody else needs to be able to check it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-09-o2-c1', 'mission-ai-experimentation-09-o2', 1, 'investigation', 'Which evidence shows a claimed result failing to reproduce?', '{"evidence":[{"id":"e1","label":"Rerun log","detail":"Same code, same data, only the random seed changed -- accuracy dropped from 94% to 78%, a swing far larger than normal noise"},{"id":"e2","label":"Rerun log B","detail":"Same code, same data, same seed -- accuracy matched the original run within a fraction of a percent"},{"id":"e3","label":"Hardware note","detail":"The rerun used a different but equivalent GPU model"}],"question":"Which evidence shows the claimed result failing to reproduce?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-experimentation-10-o1-c1', 'mission-ai-experimentation-10-o1', 1, 'multiple_choice', 'What is the actual purpose of logging every experiment run -- config, data version, seed, and metrics?', '{"question":"What is the actual purpose of logging every experiment run -- config, data version, seed, and metrics?","options":[{"id":"a","text":"To make the training script run faster"},{"id":"b","text":"So any past result can be traced back to the exact settings that produced it, instead of relying on memory or file naming conventions"},{"id":"c","text":"It has no practical purpose, only bureaucratic value"},{"id":"d","text":"To reduce the number of hyperparameters available"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-10-o2-c1', 'mission-ai-experimentation-10-o2', 1, 'investigation', 'Which evidence shows a run that cannot actually be trusted, because it was never properly logged?', '{"evidence":[{"id":"e1","label":"File listing","detail":"final_v2_REAL.py and final_v2_REAL_ACTUAL.py both exist, neither with a record of which hyperparameters or data version produced the reported score"},{"id":"e2","label":"Tracking dashboard entry","detail":"Run ID 4471: config, data version, seed and all metrics logged automatically, linked to a specific commit hash"},{"id":"e3","label":"Tracking dashboard entry B","detail":"Run ID 4472: config, data version, seed and all metrics logged automatically, linked to a specific commit hash"}],"question":"Which evidence shows a run that cannot be trusted because it was never properly logged?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-experimentation-11-o1-c1', 'mission-ai-experimentation-11-o1', 1, 'multiple_choice', 'Why can picking a model on raw accuracy alone be the wrong call?', '{"question":"Why can picking a model on raw accuracy alone be the wrong call?","options":[{"id":"a","text":"Accuracy is never a meaningful metric under any circumstances"},{"id":"b","text":"Because real deployment has other constraints too -- latency, memory, fairness across groups, cost to retrain -- that a single accuracy number ignores"},{"id":"c","text":"Because higher accuracy always means slower inference, without exception"},{"id":"d","text":"Because accuracy cannot be measured on a validation set"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-experimentation-11-o2-c1', 'mission-ai-experimentation-11-o2', 1, 'investigation', 'Two models are candidates for a real-time production system with a strict latency budget. Which is actually the better choice?', '{"evidence":[{"id":"e1","label":"Model A","detail":"94.2% accuracy, 340ms average inference time -- exceeds the system''s 100ms latency budget"},{"id":"e2","label":"Model B","detail":"93.9% accuracy, 45ms average inference time -- comfortably within the system''s 100ms latency budget"},{"id":"e3","label":"Model C","detail":"94.3% accuracy, requires a GPU unavailable in the production environment"}],"question":"Given a strict 100ms latency budget and no GPU available in production, which model is actually the right choice?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-experimentation-12-o1-c1', 'mission-ai-experimentation-12-o1', 1, 'investigation', 'Was the original comparison between the old model and the new variant actually controlled?', '{"evidence":[{"id":"e1","label":"Original run config diff","detail":"The new variant was scored on a newer evaluation set that turned out to be measurably easier -- fewer edge cases -- than the set the old model was scored on, alongside an architecture change"},{"id":"e2","label":"Team notes","detail":"Everyone agreed the new variant looked promising"},{"id":"e3","label":"Compute log","detail":"The new variant''s run used a newer GPU generation than the old model''s run"}],"question":"Which evidence shows the original comparison was not actually controlled?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-experimentation-12-o2-c1', 'mission-ai-experimentation-12-o2', 1, 'investigation', 'Does the variant''s improvement survive a change of random seed?', '{"evidence":[{"id":"e1","label":"Seed sweep","detail":"Rerunning the new variant with five different random seeds, on the old model''s original evaluation set, produces scores ranging from barely above the old model to slightly below it -- the original win only appeared with one specific seed"},{"id":"e2","label":"Single original run","detail":"The one run that produced the headline number, with no seed variation ever checked"},{"id":"e3","label":"Hardware note","detail":"All seed-sweep runs used identical hardware"}],"question":"Which evidence shows whether the improvement survives a change of random seed?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-experimentation-12-o3-c1', 'mission-ai-experimentation-12-o3', 1, 'investigation', 'What does a real, controlled ablation actually show explains the score difference?', '{"evidence":[{"id":"e1","label":"Ablation: revert to old evaluation set, average across seeds","detail":"With a matched evaluation set and averaged across seeds, the new variant''s advantage over the old model collapses to within normal run-to-run noise"},{"id":"e2","label":"Ablation: remove the new normalization layer","detail":"Score barely changes -- this component was never the source of the improvement"},{"id":"e3","label":"Ablation: remove extra training epochs","detail":"Score barely changes -- this was never the source either"}],"question":"Which ablation result actually explains what caused the original score difference?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-experimentation-12-o4-c1', 'mission-ai-experimentation-12-o4', 1, 'boss_encounter', 'Having audited the comparison, tested seed sensitivity, and run the real ablation, state whether the new variant''s improvement is real.', '{"stages":[{"objectiveRef":"mission-ai-experimentation-12-o1","label":"Audit the comparison"},{"objectiveRef":"mission-ai-experimentation-12-o2","label":"Test seed sensitivity"},{"objectiveRef":"mission-ai-experimentation-12-o3","label":"Run the real ablation"}],"task":"State the verdict: is the new variant''s improvement real, or does it collapse under a controlled, seed-averaged, properly ablated comparison?"}'::jsonb, '{"requiredObjectiveIds":["mission-ai-experimentation-12-o1","mission-ai-experimentation-12-o2","mission-ai-experimentation-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-experimentation-01-o1-c1', 'orientation', 'Think about what a genuine breakthrough and an unnoticed mistake would each look like from the outside, before any checking has happened.', 10, 1),
  ('mission-ai-experimentation-01-o1-c1', 'solution', 'Treat it as suspicious until checked -- an unusually strong first-try result and an unnoticed bug produce identical-looking numbers.', 20, 2),
  ('mission-ai-experimentation-01-o2-c1', 'orientation', 'A real hypothesis names a specific mechanism and could, in principle, turn out to be false.', 10, 1),
  ('mission-ai-experimentation-01-o2-c1', 'solution', '"Adding the extra normalization layer will reduce validation error, holding data and setup fixed" is specific and falsifiable -- the others are just enthusiasm.', 20, 2),

  ('mission-ai-experimentation-02-o1-c1', 'orientation', 'A percentage alone says nothing about whether it was hard or easy to achieve.', 10, 1),
  ('mission-ai-experimentation-02-o1-c1', 'solution', 'It needs a baseline -- some simple comparison point that tells you whether 94% is impressive or trivial.', 20, 2),
  ('mission-ai-experimentation-02-o2-c1', 'orientation', 'A baseline should be informative, not just easy to beat by accident.', 10, 1),
  ('mission-ai-experimentation-02-o2-c1', 'concept', 'On heavily imbalanced data, a majority-class guess can already score deceptively high -- that makes it the baseline everything else has to clear, not the goal itself.', 20, 2),
  ('mission-ai-experimentation-02-o2-c1', 'solution', 'e1: the always-predict-normal baseline already reaches 98% accuracy without detecting a single real event -- that is exactly the bar any real model has to actually clear.', 30, 3),

  ('mission-ai-experimentation-03-o1-c1', 'orientation', 'Think about how many things can change between two runs before you lose the ability to say what caused a difference.', 10, 1),
  ('mission-ai-experimentation-03-o1-c1', 'solution', 'A controlled experiment changes exactly one variable and holds everything else fixed, so any result difference can be attributed to that one change.', 20, 2),
  ('mission-ai-experimentation-03-o2-c1', 'orientation', 'Look for a run where more than one thing changed at once.', 10, 1),
  ('mission-ai-experimentation-03-o2-c1', 'solution', 'e1: architecture, learning rate, and the data split all changed together -- there is no way to credit the improvement to any one of them.', 20, 2),

  ('mission-ai-experimentation-04-o1-c1', 'orientation', 'Ask whether backpropagation ever touches this value directly, or whether it has to be set before training starts.', 10, 1),
  ('mission-ai-experimentation-04-o1-c1', 'solution', 'A hyperparameter is set before training and is not itself updated by the training process -- learning rate and batch size are classic examples.', 20, 2),
  ('mission-ai-experimentation-04-o2-c1', 'orientation', 'Ask what the test set is supposed to represent, and whether that meaning survives being checked over and over during tuning.', 10, 1),
  ('mission-ai-experimentation-04-o2-c1', 'solution', 'Repeatedly checking the test set during tuning leaks it into the process -- the final score no longer reflects genuinely unseen data.', 20, 2),

  ('mission-ai-experimentation-05-o1-c1', 'orientation', 'A wide gap between the two curves signals one problem. Both curves being close together but stuck high signals a different one.', 10, 1),
  ('mission-ai-experimentation-05-o1-c1', 'solution', 'Both curves flattening high and close together means underfitting -- the model lacks the capacity to fit the training data well in the first place.', 20, 2),
  ('mission-ai-experimentation-05-o2-c1', 'orientation', 'A persistent gap points one way. Both curves being stuck at a high value together points the other way. Both low and close together is the goal.', 10, 1),
  ('mission-ai-experimentation-05-o2-c1', 'solution', 'A wide persistent gap is high variance. Both flat and high is high bias. Both low and close is a good fit.', 20, 2),

  ('mission-ai-experimentation-06-o1-c1', 'orientation', 'High bias means the model struggles on training data too, not just on new data.', 10, 1),
  ('mission-ai-experimentation-06-o1-c1', 'solution', 'e1: both training and validation accuracy are low and close together -- the model cannot even fit its own training data well, which is high bias.', 20, 2),
  ('mission-ai-experimentation-06-o2-c1', 'orientation', 'Ask whether the model struggles everywhere, or only outside the data it trained on.', 10, 1),
  ('mission-ai-experimentation-06-o2-c1', 'concept', 'High bias tends to stay high bias even with more data, since the model''s capacity is the limiting factor, not the amount of data.', 20, 2),
  ('mission-ai-experimentation-06-o2-c1', 'solution', 'High bias: both errors high and close, more data barely helps. High variance: training error near zero, validation error much higher. Good fit: both low and close.', 30, 3),

  ('mission-ai-experimentation-07-o1-c1', 'orientation', 'The point is isolating cause, not adding complexity.', 10, 1),
  ('mission-ai-experimentation-07-o1-c1', 'solution', 'An ablation removes or disables one component at a time to measure what performance actually depends on.', 20, 2),
  ('mission-ai-experimentation-07-o2-c1', 'orientation', 'Look for the change whose removal actually moves the score by more than normal noise.', 10, 1),
  ('mission-ai-experimentation-07-o2-c1', 'solution', 'e3: reverting to the old evaluation set collapses almost the entire claimed improvement -- the easier evaluation set, not the model itself, was doing the work.', 20, 2),

  ('mission-ai-experimentation-08-o1-c1', 'orientation', 'An aggregate score is one number describing thousands of individual predictions at once.', 10, 1),
  ('mission-ai-experimentation-08-o1-c1', 'solution', 'It cannot tell you where or how the model is actually failing -- only reading individual errors can reveal that.', 20, 2),
  ('mission-ai-experimentation-08-o2-c1', 'orientation', 'Compare how much of the total dataset a category represents to how much of the errors it represents.', 10, 1),
  ('mission-ai-experimentation-08-o2-c1', 'solution', 'e1: one category is only 6% of the data but over 80% of the errors -- a concentrated failure pattern the 89% aggregate score completely hides.', 20, 2),

  ('mission-ai-experimentation-09-o1-c1', 'orientation', 'A single lucky run and a genuinely reproducible result look identical until someone reruns it.', 10, 1),
  ('mission-ai-experimentation-09-o1-c1', 'solution', 'Reproducible means the same code, data, and seed reliably produce the same result, not just on one occasion.', 20, 2),
  ('mission-ai-experimentation-09-o2-c1', 'orientation', 'Look for a rerun where only the seed changed and the result changed drastically.', 10, 1),
  ('mission-ai-experimentation-09-o2-c1', 'solution', 'e1: changing only the seed dropped accuracy from 94% to 78% -- a swing far too large to be normal noise, meaning the original result did not reproduce.', 20, 2),

  ('mission-ai-experimentation-10-o1-c1', 'orientation', 'Think about someone trying to understand a result six months after it was produced, with no memory of the details.', 10, 1),
  ('mission-ai-experimentation-10-o1-c1', 'solution', 'Logging every run lets any past result be traced back to the exact settings that produced it, instead of relying on memory or filenames.', 20, 2),
  ('mission-ai-experimentation-10-o2-c1', 'orientation', 'A filename is not a record of what config, data version, or seed actually produced a number.', 10, 1),
  ('mission-ai-experimentation-10-o2-c1', 'solution', 'e1: two files named like guesses, with no logged config, data version, or seed behind their reported score -- untraceable, and therefore untrustworthy.', 20, 2),

  ('mission-ai-experimentation-11-o1-c1', 'orientation', 'A production system has to satisfy more requirements than a single leaderboard number captures.', 10, 1),
  ('mission-ai-experimentation-11-o1-c1', 'solution', 'Real deployment has other constraints -- latency, memory, fairness, retraining cost -- that raw accuracy alone ignores entirely.', 20, 2),
  ('mission-ai-experimentation-11-o2-c1', 'orientation', 'Rule out any model that cannot even run within the stated constraints, regardless of its accuracy.', 10, 1),
  ('mission-ai-experimentation-11-o2-c1', 'solution', 'e2: Model B is the only one that fits inside the 100ms latency budget with no GPU requirement -- the other two are disqualified by the constraints before accuracy even matters.', 20, 2),

  ('mission-ai-experimentation-12-o1-c1', 'orientation', 'A controlled comparison should hold everything fixed except the one thing being tested.', 10, 1),
  ('mission-ai-experimentation-12-o1-c1', 'solution', 'e1: the new variant was scored on a measurably easier evaluation set while also changing the architecture -- multiple uncontrolled changes at once.', 20, 2),
  ('mission-ai-experimentation-12-o2-c1', 'orientation', 'A result that depends on one specific random seed is not a stable result.', 10, 1),
  ('mission-ai-experimentation-12-o2-c1', 'solution', 'e1: across five different seeds on the original evaluation set, the win disappears -- it only ever showed up with the one seed that produced the headline number.', 20, 2),
  ('mission-ai-experimentation-12-o3-c1', 'orientation', 'Look for the ablation that matches an evaluation-set change, not a model-component change.', 10, 1),
  ('mission-ai-experimentation-12-o3-c1', 'solution', 'e1: matching the evaluation set and averaging across seeds collapses the advantage to normal noise -- the easier evaluation set and a lucky seed explain the result, not the model.', 20, 2),
  ('mission-ai-experimentation-12-o4-c1', 'orientation', 'Look at what all three checks agreed on, not at how good the original headline number looked.', 15, 1),
  ('mission-ai-experimentation-12-o4-c1', 'solution', 'The improvement is not real. It came from an uncontrolled, easier evaluation set and a lucky random seed, not from anything the new variant actually does better -- it does not survive a controlled ablation.', 25, 2);
